<?php require __DIR__ . '/../vendor/autoload.php'; $app = require_once __DIR__ . '/../bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Http\Kernel::class); $kernel->bootstrap(); header('Content-Type: text/plain'); header('Content-Disposition: attachment; filename="fresh_backup.sql"'); $tables = Illuminate\Support\Facades\DB::select('SHOW TABLES'); echo "SET FOREIGN_KEY_CHECKS=0;\nSET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';\nSET NAMES utf8mb4;\n\n"; foreach ($tables as $t) { $vars = get_object_vars($t); $tableName = reset($vars); $create = Illuminate\Support\Facades\DB::select("SHOW CREATE TABLE `{$tableName}`"); $createVars = get_object_vars($create[0]); $createSql = end($createVars); echo "DROP TABLE IF EXISTS `{$tableName}`;\n" . $createSql . ";\n\n"; $rows = Illuminate\Support\Facades\DB::table($tableName)->get(); if ($rows->count() > 0) { foreach ($rows->chunk(50) as $chunk) { $firstRow = (array)$chunk->first(); $cols = "`" . implode("`,`", array_keys($firstRow)) . "`"; echo "INSERT INTO `{$tableName}` ({$cols}) VALUES\n"; $valRows = []; foreach ($chunk as $r) { $vals = array_map(function($val) { return $val === null ? 'NULL' : Illuminate\Support\Facades\DB::getPdo()->quote($val); }, (array)$r); $valRows[] = "(" . implode(",", $vals) . ")"; } echo implode(",\n", $valRows) . ";\n\n"; } } } echo "SET FOREIGN_KEY_CHECKS=1;\n";